SET GLOBAL slow_query_log = ON;
SET GLOBAL long_query_time = 1;
SET GLOBAL log_queries_not_using_indexes = ON;

# Time: 2024-07-29T14:23:05.123456Z
# User@Host: root[root] @ localhost []
# Query_time: 3.456789  Lock_time: 0.000123  Rows_sent: 1  Rows_examined: 2000000
SET timestamp=1722258185;
SELECT * FROM task_records WHERE user_id = 12345 AND status = 'completed';

-- 这条 SQL 每次执行都要扫 500 万行 SELECT * FROM task_records WHERE user_id = 12345;
-- EXPLAIN 显示：type: ALL, key: NULL, rows: 5000000
-- 解决：给 user_id 加索引 ALTER TABLE task_records ADD INDEX idx_user_id (user_id);
-- 加完后：type: ref, key: idx_user_id, rows: 5 -- 从扫 500 万行变成扫 5 行！

-- ❌ 返回所有字段，包括大文本字段
SELECT * FROM history WHERE user_id = 12345;

-- ✅ 只查需要的字段，传输数据量小很多
SELECT id, created_at, status FROM history WHERE user_id = 12345;

// 创建索引
db.users.createIndex({city: 1})

// 创建复合索引
db.users.createIndex({city: 1, name: 1})

// 删除索引
db.users.dropIndex("city_1")

// 查看所有索引
db.users.getIndexes()

// ❌ 不能触发覆盖查询——默认返回 _id，而 _id 不在 city 索引里
db.users.find({ city: "北京" }, { city: 1 })
// 实际返回：{ _id: xxx, city: "北京" }

// ✅ 显式排除 _id，就能触发覆盖查询
db.users.find({ city: "北京" }, { city: 1, _id: 0 })
// 实际返回：{ city: "北京" }
